{
  "claims": [
    {
      "kind": "qualitative",
      "text": "Carnival is the largest global cruise company and among the largest leisure travel companies.",
      "citations": [
        {
          "chunk_id": "CCL-000081509726000007-0011",
          "quote": "We are the largest global cruise company, and among the largest leisure travel companies"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Its portfolio spans eight cruise lines, including AIDA Cruises, Carnival Cruise Line, Costa Cruises, Cunard, Holland America Line, P&O Cruises, Princess Cruises and Seabourn, and each brand targets a distinct set of consumer psychographics and vacation needs, allowing it to penetrate large addressable customer segments.",
      "citations": [
        {
          "chunk_id": "CCL-000081509726000007-0011",
          "quote": "with a portfolio of world-class cruise lines - AIDA Cruises, Carnival Cruise Line, Costa Cruises, Cunard, Holland America Line, P&O Cruises, Princess Cruises and Seabourn."
        },
        {
          "chunk_id": "CCL-000081509726000007-0016",
          "quote": "Each brand in our portfolio meets the needs of a distinct set of consumer psychographics and vacation needs which allows us to penetrate large addressable customer segments."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The mobility of cruise ships enables the company to move vessels between regions to meet changing demand across different geographic areas.",
      "citations": [
        {
          "chunk_id": "CCL-000081509726000007-0016",
          "quote": "The mobility of cruise ships enables us to move our vessels between regions in order to meet changing demand across different geographic areas."
        }
      ]
    },
    {
      "kind": "quantitative",
      "text": "Revenue increased from {{m:revenue:FY-2}} in {{p:FY-2}} to {{m:revenue:FY0}} in {{p:FY0}} and {{m:revenue:LTM}} in {{p:LTM}}; EBITDA was {{m:ebitda:FY0}} in {{p:FY0}} and {{m:ebitda:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "In {{p:FY0}}, no group of travel agencies under common control accounted for 10% or more of our revenues, indicating diversified distribution channels.",
      "citations": [
        {
          "chunk_id": "CCL-000081509726000007-0030",
          "quote": "no group of travel agencies under common control accounted for 10% or more of our revenues"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Overcapacity and competition in the cruise and land-based vacation industry may negatively impact cruise sales, pricing and destination options, a source of cash flow volatility.",
      "citations": [
        {
          "chunk_id": "CCL-000081509726000037-0039",
          "quote": "Overcapacity and competition in the cruise and land-based vacation industry may negatively impact our cruise sales, pricing and destination options."
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "Debt / EBITDA improved from {{m:debt_to_ebitda:FY-2}} in {{p:FY-2}} to {{m:debt_to_ebitda:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "Net leverage improved from {{m:net_leverage:FY-2}} in {{p:FY-2}} to {{m:net_leverage:LTM}} in {{p:LTM}}, as total debt declined from {{m:total_debt:FY0}} in {{p:FY0}} to {{m:total_debt:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "EBITDA / interest improved from {{m:interest_coverage:FY-2}} in {{p:FY-2}} to {{m:interest_coverage:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "FCF / debt improved from {{m:fcf_to_debt:FY-2}} in {{p:FY-2}} to {{m:fcf_to_debt:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "Operating cash flow increased on improved earnings, while capital expenditures remained focused on ship improvements, the new shipbuilding program, and destination development.",
      "citations": [
        {
          "chunk_id": "CCL-000081509726000107-0054",
          "quote": "Our business provided $5.3 billion of net cash flows from operating activities"
        },
        {
          "chunk_id": "CCL-000081509726000107-0054",
          "quote": "This was caused by an improvement in our earnings"
        },
        {
          "chunk_id": "CCL-000081509726000107-0054",
          "quote": "Capital expenditures of $2.1 billion principally attributable to ship improvements, our ongoing new shipbuilding program and development of our portfolio of exclusive destinations"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "During {{p:FY0}}, the company entered into debt transactions involving issuance of new debt, modification and extinguishment of existing debt, and refinancing of existing syndicated debt.",
      "citations": [
        {
          "chunk_id": "CCL-000081509726000007-0222",
          "quote": "issuance of new debt, modification and extinguishment of existing debt, and refinancing of existing syndicated debt"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "For {{p:LTM}}, the reported liquidity coverage ratio was {{m:liquidity_coverage:LTM}}, and for {{p:FY0}} it was {{m:liquidity_coverage:FY0}}, indicating that defined sources exceeded defined uses in both periods.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "At the end of {{p:LTM}}, the company had $5.7 billion of total liquidity, including {{m:cash:LTM}} of cash and cash equivalents and $4.5 billion available for borrowing under its multicurrency revolving credit facility.",
      "citations": [
        {
          "chunk_id": "CCL-000081509726000107-0053",
          "quote": "$5.7 billion of liquidity including $1.2 billion of cash and cash equivalents and $4.5 billion available for borrowing under our multicurrency revolving credit facility"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "At the end of {{p:LTM}}, the company also had $10.7 billion of undrawn export credit facilities to fund future ship deliveries.",
      "citations": [
        {
          "chunk_id": "CCL-000081509726000107-0053",
          "quote": "we had $10.7 billion of undrawn export credit facilities to fund future ship deliveries"
        }
      ]
    },
    {
      "kind": "quantitative",
      "text": "For {{p:LTM}}, cash from operations of {{m:cfo:LTM}} exceeded the sum of short-term debt of {{m:short_term_debt:LTM}} and capital expenditures of {{m:capex:LTM}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "The company operates with a substantial working capital deficit, and customer deposits are used alongside other cash sources to fund operations, service debt, and support capital investments.",
      "citations": [
        {
          "chunk_id": "CCL-000081509726000107-0053",
          "quote": "These customer deposits are used alongside other cash sources to fund operations, service debt, and support capital investments"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "As of {{p:FY0}}, scheduled debt maturities were {{m:maturity_year_1:FY0}} in the next twelve months, {{m:maturity_year_2:FY0}} in year two, {{m:maturity_year_3:FY0}} in year three, {{m:maturity_year_4:FY0}} in year four, {{m:maturity_year_5:FY0}} in year five and {{m:maturity_after_year_5:FY0}} thereafter.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "Debt due within 24 months was {{m:debt_due_24m:FY0}}, representing {{m:share_due_24m:FY0}} of total debt of {{m:total_debt:FY0}}, and near-term maturity cover was {{m:near_term_maturity_cover:FY0}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "During {{p:FY0}}, the company issued senior unsecured notes and borrowed under unsecured term loan facilities, and used proceeds from those debt issuances and borrowings together with cash on hand to prepay outstanding debt, recognizing debt extinguishment and modification costs.",
      "citations": [
        {
          "chunk_id": "CCL-000081509726000007-0179",
          "quote": "we used proceeds from debt issuances and borrowings, together with cash on hand, to prepay the following debt instruments:"
        },
        {
          "chunk_id": "CCL-000081509726000007-0180",
          "quote": "we recognized a total of $409 million of debt extinguishment and modification costs"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "As of {{p:FY0}}, the company was in compliance with applicable covenants under its debt agreements.",
      "citations": [
        {
          "chunk_id": "CCL-000081509726000007-0183",
          "quote": "we were in compliance with the applicable covenants under our debt agreements"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The debt agreements contain cross-default and/or cross-acceleration clauses under which substantially all outstanding debt could become due upon an event of default.",
      "citations": [
        {
          "chunk_id": "CCL-000081509726000007-0183",
          "quote": "if an event of default under any debt agreement occurs, then, pursuant to cross-default and/or cross-acceleration clauses therein, substantially all of our outstanding debt could become due"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "As of {{p:LTM}}, all outstanding debt was issued or guaranteed by substantially the same entities with the exception of $1.7 billion of export credit facilities of Sun Princess Limited and Sun Princess II Limited, which do not guarantee the company's other outstanding debt.",
      "citations": [
        {
          "chunk_id": "CCL-000081509726000107-0020",
          "quote": "the $1.7 billion of export credit facilities of Sun Princess Limited and Sun Princess II Limited, which do not guarantee our other outstanding debt"
        }
      ]
    }
  ]
}

